25: /// 4xf32 color using internal gamma.
26: ///
27: /// ARGB layout is important for x86 SIMD.
28: /// I've created the newtype wrapper to try a 16-byte alignment, but it didn't improve perf :(
29: #[cfg_attr(
30:     any(target_arch = "x86_64", all(target_feature = "neon", target_arch = "aarch64"), all(target_arch = "wasm32", target_feature = "simd128")),
