37: impl f_pixel {
38:     #[cfg(not(any(target_arch = "x86_64", all(target_feature = "neon", target_arch = "aarch64"), all(target_arch = "wasm32", target_feature = "simd128"))))]
39:     #[inline(always)]
40:     pub fn diff(&self, other: &f_pixel) -> f32 {
41:         let alphas = other.0.a - self.0.a;
42:         let black = self.0 - other.0;
43:         let white = ARGBF {
44:             a: 0.,
45:             r: black.r + alphas,
46:             g: black.g + alphas,
47:             b: black.b + alphas,
48:         };
49:         (black.r * black.r).max(white.r * white.r) +
50:         (black.g * black.g).max(white.g * white.g) +
51:         (black.b * black.b).max(white.b * white.b)
52:     }
53: 
54:     #[cfg(all(target_arch = "wasm32", target_feature = "simd128"))]
55:     #[inline(always)]
56:     pub fn diff(&self, other: &f_pixel) -> f32 {
57:         use core::arch::wasm32::*;
58: 
59:         let px = f32x4(self.0.a, self.0.r, self.0.g, self.0.b);
60:         let py = f32x4(other.0.a, other.0.r, other.0.g, other.0.b);
61: 
62:         // y.a - x.a, then broadcast lane 0 to all four
63:         let alpha_diff = f32x4_sub(py, px);
64:         let alphas = f32x4_splat(f32x4_extract_lane::<0>(alpha_diff));
65: 
66:         let mut onblack = f32x4_sub(px, py); // x - y
67:         let mut onwhite = f32x4_add(onblack, alphas); // x - y + (y.a - x.a)
68: 
69:         onblack = f32x4_mul(onblack, onblack);
70:         onwhite = f32x4_mul(onwhite, onwhite);
71:         let max = f32x4_max(onwhite, onblack);
72: 
73:         // add rgb (lanes 1,2,3), not a (lane 0)
74:         f32x4_extract_lane::<1>(max)
75:             + f32x4_extract_lane::<2>(max)
76:             + f32x4_extract_lane::<3>(max)
77:     }
78: 
79:     #[cfg(all(target_feature = "neon", target_arch = "aarch64"))]
80:     #[inline(always)]
81:     pub fn diff(&self, other: &Self) -> f32 {
82:         unsafe {
83:             use core::arch::aarch64::*;
84: 
85:             let px = vld1q_f32((self as *const Self).cast::<f32>());
86:             let py = vld1q_f32((other as *const Self).cast::<f32>());
87: 
88:             // y.a - x.a
89:             let mut alphas = vsubq_f32(py, px);
90:             alphas = vdupq_laneq_f32(alphas, 0); // copy first to all four
91: 
92:             let mut onblack = vsubq_f32(px, py); // x - y
93:             let mut onwhite = vaddq_f32(onblack, alphas); // x - y + (y.a - x.a)
94: 
95:             onblack = vmulq_f32(onblack, onblack);
96:             onwhite = vmulq_f32(onwhite, onwhite);
97: 
98:             let max = vmaxq_f32(onwhite, onblack);
99: 
100:             let mut max_r = [0.; 4];
101:             vst1q_f32(max_r.as_mut_ptr(), max);
102: 
103:             let mut max_gb = [0.; 4];
104:             vst1q_f32(max_gb.as_mut_ptr(), vpaddq_f32(max, max));
105: 
106:             // add rgb, not a
107: 
108:             max_r[1] + max_gb[1]
109:         }
110:     }
111: 
112:     #[cfg(target_arch = "x86_64")]
113:     #[inline(always)]
114:     pub fn diff(&self, other: &f_pixel) -> f32 {
115:         unsafe {
116:             use core::arch::x86_64::*;
117: 
118:             let px = _mm_loadu_ps(self as *const f_pixel as *const f32);
119:             let py = _mm_loadu_ps(other as *const f_pixel as *const f32);
120: 
121:             // y.a - x.a
122:             let mut alphas = _mm_sub_ss(py, px);
123:             alphas = _mm_shuffle_ps(alphas, alphas, 0); // copy first to all four
124: 
125:             let mut onblack = _mm_sub_ps(px, py); // x - y
126:             let mut onwhite = _mm_add_ps(onblack, alphas); // x - y + (y.a - x.a)
127: 
128:             onblack = _mm_mul_ps(onblack, onblack);
129:             onwhite = _mm_mul_ps(onwhite, onwhite);
130:             let max = _mm_max_ps(onwhite, onblack);
131: 
132:             // the compiler is better at horizontal add than I am
133:             let mut tmp = [0.; 4];
134:             _mm_storeu_ps(tmp.as_mut_ptr(), max);
135: 
136:             // add rgb, not a
137:             let res = tmp[1] + tmp[2] + tmp[3];
138:             res
139:         }
140:     }
