142:     #[inline]
143:     pub(crate) fn to_rgb(self, gamma: f64) -> RGBA {
144:         if self.is_fully_transparent() {
145:             return RGBA::new(0, 0, 0, 0);
146:         }
147: 
148:         let r = (f64::from(LIQ_WEIGHT_A) / f64::from(LIQ_WEIGHT_R)) as f32 * self.r / self.a;
149:         let g = (f64::from(LIQ_WEIGHT_A) / f64::from(LIQ_WEIGHT_G)) as f32 * self.g / self.a;
150:         let b = (f64::from(LIQ_WEIGHT_A) / f64::from(LIQ_WEIGHT_B)) as f32 * self.b / self.a;
151: 
152:         let gamma = (gamma / INTERNAL_GAMMA) as f32;
153:         debug_assert!(gamma.is_finite());
154: 
155:         // 256, because numbers are in range 1..255.9999… rounded down
156:         RGBA {
157:             r: (r.max(0.).powf(gamma) * 256.) as u8,
158:             g: (g.max(0.).powf(gamma) * 256.) as u8,
159:             b: (b.max(0.).powf(gamma) * 256.) as u8,
160:             a: (self.a * (256. / f64::from(LIQ_WEIGHT_A)) as f32) as u8,
161:         }
162:     }
