164:     pub fn from_rgba(gamma_lut: &[f32; 256], px: RGBA) -> Self {
165:         let a = f32::from(px.a) / 255.;
166:         Self(ARGBF {
167:             a: a * LIQ_WEIGHT_A,
168:             r: gamma_lut[px.r as usize] * LIQ_WEIGHT_R * a,
169:             g: gamma_lut[px.g as usize] * LIQ_WEIGHT_G * a,
170:             b: gamma_lut[px.b as usize] * LIQ_WEIGHT_B * a,
171:         })
172:     }
