175:     pub(crate) fn is_fully_transparent(self) -> bool {
176:         self.a < (1. / 255. * f64::from(LIQ_WEIGHT_A)) as f32
177:     }
178: 
179:     #[inline]
180:     pub(crate) fn is_fully_opaque(self) -> bool {
181:         self.a >= (255. / 256. * f64::from(LIQ_WEIGHT_A)) as f32
182:     }
183: }
