253: /// A palette of premultiplied ARGB 4xf32 colors in internal gamma
254: #[derive(Clone)]
255: pub(crate) struct PalF {
256:     colors: ArrayVec<f_pixel, MAX_COLORS>,
257:     pops: ArrayVec<PalPop, MAX_COLORS>,
258: }
259: 
260: impl PalF {
261:     #[inline]
262:     pub fn new() -> Self {
263:         debug_assert!(PalIndex::MAX as usize + 1 >= MAX_COLORS);
264:         debug_assert!(PalLen::MAX as usize >= MAX_COLORS);
265:         Self {
266:             colors: ArrayVec::default(),
267:             pops: ArrayVec::default(),
268:         }
269:     }
270: 
271:     #[inline(always)]
272:     pub fn push(&mut self, color: f_pixel, popularity: PalPop) {
273:         self.pops.push(popularity);
274:         self.colors.push(color);
275:     }
276: 
277:     pub fn set(&mut self, idx: usize, color: f_pixel, popularity: PalPop) {
278:         debug_assert!(idx < self.colors.len() && idx < self.pops.len());
279: 
280:         if let Some(pops_idx) = self.pops.get_mut(idx) {
281:             *pops_idx = popularity;
282:         }
283:         if let Some(colors_idx) = self.colors.get_mut(idx) {
284:             *colors_idx = color;
285:         }
286:     }
287: 
288:     #[inline(always)]
289:     pub fn as_slice(&self) -> &[f_pixel] {
290:         &self.colors
291:     }
292: 
293:     #[inline(always)]
294:     pub fn pop_as_slice(&self) -> &[PalPop] {
295:         &self.pops
296:     }
297: 
298:     // this is max colors allowed by the user, not just max in the current (candidate/low-quality) palette
299:     pub(crate) fn with_fixed_colors(mut self, max_colors: PalLen, fixed_colors: &[f_pixel]) -> Self {
300:         if fixed_colors.is_empty() {
301:             return self;
302:         }
303: 
304:         // if using low quality, there's a chance mediancut won't create enough colors in the palette
305:         let max_fixed_colors = fixed_colors.len().min(max_colors as usize);
306:         if self.len() < max_fixed_colors {
307:             let needs_extra = max_fixed_colors - self.len();
308:             self.colors.extend(fixed_colors.iter().copied().take(needs_extra));
309:             self.pops.extend(iter::repeat(PalPop::new(0.)).take(needs_extra));
310:             debug_assert_eq!(self.len(), max_fixed_colors);
311:         }
312: 
313:         // since the fixed colors were in the histogram, expect them to be in the palette,
314:         // and change closest existing one to be exact fixed
315:         for (i, fixed_color) in fixed_colors.iter().enumerate().take(self.len()) {
316:             let (best_idx, _) = self.colors.iter().enumerate().skip(i).min_by_key(|(_, pal_color)| {
317:                 // not using Nearest, because creation of the index may take longer than naive search once
318:                 OrdFloat::new(pal_color.diff(fixed_color))
319:             }).expect("logic bug in fixed colors, please report a bug");
320:             debug_assert!(best_idx >= i);
321:             self.swap(i, best_idx);
322:             self.set(i, *fixed_color, self.pops[i].to_fixed());
323:         }
324: 
325:         debug_assert!(self.colors.iter().zip(fixed_colors).all(|(p, f)| p == f));
326:         debug_assert!(self.pops.iter().take(fixed_colors.len()).all(|pop| pop.is_fixed()));
327:         self
328:     }
329: 
330:     #[inline(always)]
331:     pub(crate) fn len(&self) -> usize {
332:         debug_assert_eq!(self.colors.len(), self.pops.len());
333:         self.colors.len()
334:     }
