336:     #[inline(always)]
337:     pub fn iter_mut(&mut self) -> impl Iterator<Item = (&mut f_pixel, &mut PalPop)> {
338:         let c = &mut self.colors[..];
339:         let pop = &mut self.pops[..c.len()];
