349:     /// Also rounds the input pal
350:     pub(crate) fn init_int_palette(&mut self, int_palette: &mut Palette, gamma: f64, posterize: u8) {
351:         let lut = gamma_lut(gamma);
352:         for ((f_color, f_pop), int_pal) in self.iter_mut().zip(&mut int_palette.entries) {
353:             let mut px = f_color.to_rgb(gamma)
354:                 .map(move |c| posterize_channel(c, posterize));
355:             *f_color = f_pixel::from_rgba(&lut, px);
356:             if px.a == 0 && !f_pop.is_fixed() {
357:                 px.r = 71u8;
358:                 px.g = 112u8;
359:                 px.b = 76u8;
360:             }
361:             *int_pal = px;
362:         }
363:         int_palette.count = self.len() as _;
364:     }
365: }
