367: #[inline]
368: const fn posterize_channel(color: u8, bits: u8) -> u8 {
369:     if bits == 0 {
370:         color
371:     } else {
372:         (color & !((1 << bits) - 1)) | (color >> (8 - bits))
373:     }
374: }
