376: #[inline(always)]
377: pub fn gamma_lut(gamma: f64) -> [f32; 256] {
378:     debug_assert!(gamma > 0.);
379:     let mut tmp = [0.; 256];
380:     for (i, t) in tmp.iter_mut().enumerate() {
381:         *t = ((i as f32) / 255.).powf((INTERNAL_GAMMA / gamma) as f32);
382:     }
383:     tmp
384: }
