108: fn get_dithered_pixel(dither_level: f32, max_dither_error: f32, thiserr: f_pixel, px: f_pixel) -> f_pixel {
109:     let s = thiserr.0 * dither_level;
110:     // This prevents gaudy green pixels popping out of the blue (or red or black! ;)
111:     let dither_error = s.r.mul_add(s.r, s.g * s.g) + s.b.mul_add(s.b, s.a * s.a);
112:     if dither_error < 2. / 256. / 256. {
113:         // don't dither areas that don't have noticeable error — makes file smaller
114:         return px;
115:     }
116: 
117:     let mut ratio: f32 = 1.;
118:     const MAX_OVERFLOW: f32 = 1.1;
119:     const MAX_UNDERFLOW: f32 = -0.1;
120:     // allowing some overflow prevents undithered bands caused by clamping of all channels
121:     if px.r + s.r > MAX_OVERFLOW {
122:         ratio = ratio.min((MAX_OVERFLOW - px.r) / s.r);
123:     } else if px.r + s.r < MAX_UNDERFLOW {
124:         ratio = ratio.min((MAX_UNDERFLOW - px.r) / s.r);
125:     }
126:     if px.g + s.g > MAX_OVERFLOW {
127:         ratio = ratio.min((MAX_OVERFLOW - px.g) / s.g);
128:     } else if px.g + s.g < MAX_UNDERFLOW {
129:         ratio = ratio.min((MAX_UNDERFLOW - px.g) / s.g);
130:     }
131:     if px.b + s.b > MAX_OVERFLOW {
132:         ratio = ratio.min((MAX_OVERFLOW - px.b) / s.b);
133:     } else if px.b + s.b < MAX_UNDERFLOW {
134:         ratio = ratio.min((MAX_UNDERFLOW - px.b) / s.b);
135:     }
136:     if dither_error > max_dither_error {
137:         ratio *= 0.8;
138:     }
139:     f_pixel(ARGBF {
140:         a: (px.a + s.a).clamp(0., 1.),
141:         r: s.r.mul_add(ratio, px.r),
142:         g: s.g.mul_add(ratio, px.g),
143:         b: s.b.mul_add(ratio, px.b),
144:     })
145: }
