98: macro_rules! bad_object {
99:     ($obj:expr, $tag:expr) => {{
100:         let obj = &*$obj;
101:         #[allow(unused_unsafe)]
102:         #[allow(clippy::ptr_as_ptr)]
103:         let bork = if cfg!(miri) { false } else { unsafe { liq_received_invalid_pointer((obj as *const _ as *const u8)) } };
104:         (bork || (($obj).magic_header != $tag))
105:     }};
