207: unsafe fn attr_to_liq_attr_ptr(ptr: &Attributes) -> &liq_attr {
208:     let liq_attr = ptr::NonNull::<liq_attr>::dangling();
209:     let outer_addr = ptr::addr_of!(*liq_attr.as_ptr()) as isize;
210:     let inner_addr = ptr::addr_of!((*liq_attr.as_ptr()).inner) as isize;
211: 
212:     &*(ptr as *const Attributes).cast::<u8>().offset(outer_addr - inner_addr).cast::<liq_attr>()
213: }
